extern "C" bool g_sessionClientStaysInRoom;
// Recovered structural path from D2Game.0x6FC33670, normally called once per active client/frame.
void __fastcall sub_6FC33670(D2GameStrc* pGame, D2ClientStrc* pClient) {
    if (!pGame || !pClient) return;
    D2UnitStrc* player = CLIENTS_GetPlayerFromClient(pClient, 0);
    if (!player) return;
    D2ActiveRoomStrc* clientRoom = pClient->pRoom;
    D2ActiveRoomStrc* playerRoom = UNITS_GetRoom(player);
    // D24 (1.13c D2Game+0x9DCD0 order): the client's room walk sends the changed units (0x69/0x47/0x48/0x2C) and the
    // statlist diff (0x1D/E/F) before any room change; retail runs these first in sub_6FC33670.
    // Narrowest key: only the frame a level-up lands (the first frame just records the level), so sessions that never level
    // keep main's order and send nothing here.  ponytail: 8 clients, upgrade to a D2ClientStrc field if more are needed.
    static D2ClientStrc* seenClient[8]; static int32_t seenLevel[8];
    const int32_t level = STATLIST_UnitGetStatValue(player, STAT_LEVEL, 0);
    int slot = 0; while (slot < 7 && seenClient[slot] && seenClient[slot] != pClient) ++slot;
    const bool levelUp = seenClient[slot] == pClient && level != seenLevel[slot];
    seenClient[slot] = pClient; seenLevel[slot] = level;
    // D48: the walk runs every frame, as retail's does (its 0x0E/0x9C reach the session client); the level-up window only adds the stat-diff.
    if (clientRoom) {
        if (levelUp) LEVEL_RemoveUnitsExceptClientPlayer(clientRoom, pClient);
        LEVEL_UpdateUnitsInAdjacentRooms(pGame, clientRoom, pClient);
    }
    if (levelUp) {
        D2Common_10513(player, player, (void(__fastcall*)(D2UnitStrc*, int32_t, int32_t, D2UnitStrc*))D2GAME_UpdateAttribute_6FC822D0);
    }
    ++pClient->unk0x1B0;
    if (clientRoom != playerRoom && !g_sessionClientStaysInRoom) {
        const int32_t oldLevel = clientRoom ? DUNGEON_GetLevelIdFromRoom(clientRoom) : 0;
        const int32_t newLevel = playerRoom ? DUNGEON_GetLevelIdFromRoom(playerRoom) : 0;
        if (oldLevel != newLevel) {
            QUESTS_ChangeLevel(pGame, oldLevel, newLevel, player);
            SUNITPROXY_UpdateNpcsOnActChange(pGame, player, oldLevel, newLevel);
        }
        sub_6FC33020(pClient, playerRoom);
        // the player joins the queued-unit flush only on a room change; an unconditional refresh every frame made the flush
        // reset STAT_LASTEXP (0x1d) the frame an experience gain set it, where retail keeps it until the next gain
        if (UNITS_GetRoom(player)) UNITROOM_RefreshUnit(player);
    }
    ARENA_SynchronizeWithClients(pGame, pClient); // 0x65 score, retail's step between the room change and the refresh
    // The level's roof POPS, once per client frame from the player's own room and position: D2Common
    // #10012 DUNGEON_UpdatePops -> DRLGPRESET_UpdatePops, which hides the roof the preset's pop region
    // names while the player stands inside that region (and reveals it again on the way out). Its only
    // caller in retail is the client frame, which is this function's role here -- nothing in the tree
    // called it, so every roof stayed drawn and the Fortress hid the hero under one (client-parity F44).
    // The coordinates are the session's own subtile position, the unit DUNGEON_UpdatePops' region test
    // is written in (5 * the map's tile coordinate, DrlgPreset.cpp).
    if (playerRoom && player->pDynamicPath) {
        DUNGEON_UpdatePops(playerRoom, player->pDynamicPath->tGameCoords.wPosX, player->pDynamicPath->tGameCoords.wPosY, FALSE);
    }
}
// 1.13c D2Game.0x6FC3xxxx (D2MOO Clients.cpp CLIENTS_ToggleFlag): sets or clears one bit of the
// client's own save flags (D2ClientStrc::tSaveFlags, the same word PLRSAVE2_WriteSaveHeader writes
// to the .d2s header at 0x24). This was a no-op, so retail's own death path (PLRMODE_StartID_Death /
// PLRMODE_StartXY_Dead, PlrModes.cpp) calling CLIENTS_ToggleFlag(pClient, CLIENTSAVEFLAG_DEAD, TRUE)
// never actually marked a dying client dead: the flags a hardcore player read back after dying, and
// the .d2s this engine wrote for them, both stayed HARDCORE|EXPANSION with no DEAD bit, so nothing
// downstream that gates on CLIENTSAVEFLAG_DEAD (the hardcore resurrect refusal, PLRSAVE2's
// DEADHARDCORE reload check) could ever fire.
void CLIENTS_ToggleFlag(D2ClientStrc* pClient, uint16_t nFlag, int32_t bSet) {
    if (!pClient) return;
    if (bSet) pClient->tSaveFlags.nPackedValue |= nFlag;
    else pClient->tSaveFlags.nPackedValue &= ~nFlag;
}
// 1.13c D2Game.0x6FC33xxx (D2MOO Clients.cpp CLIENTS_UpdateCharacterProgression). Retail's own
// progression update, called by each act-boss quest the moment its boss dies (A1Q6 passes 1 ...
// A5Q6 passes 5): the count is the HIGH-WATER mark of act + difficulty * actsPerDifficulty, where
// actsPerDifficulty is 5 in an expansion game and 4 in classic. Those are exactly the values
// PLRSAVE2_CheckPlayerFlags gates Nightmare (>= 5 expansion / 4 classic) and Hell (>= 10 / 8) on.
// This was a no-op, so every file this engine wrote recorded progression 0 and could only ever be
// loaded back at Normal (client-parity C3p).
void CLIENTS_UpdateCharacterProgression(D2ClientStrc* pClient, uint16_t nAct, uint16_t nDifficulty)
{
    if (!pClient) return;
    const int32_t nActsPerDifficulty = pClient->tSaveFlags.bExpansion ? NUM_ACTS : (NUM_ACTS - 1);
    const int32_t nNewActDifficulty = (int32_t)nAct + (int32_t)nDifficulty * nActsPerDifficulty;
    if (nNewActDifficulty >= (int32_t)pClient->tSaveFlags.nProgression)
    {
        pClient->tSaveFlags.nProgression = (uint16_t)nNewActDifficulty;
    }
}
