    int32_t v = STATLIST_UnitGetStatValue(pMonster, STAT_VELOCITYPERCENT, 0);
    *vel = (int16_t)(v < -32768 ? -32768 : v >= 32767 ? 32767 : v);
    *maxDist = PATH_GetMaxDistance(pMonster->pDynamicPath);
    return 0;
