    b[10] = (uint8_t)life; b[11] = full ? (uint8_t)hit : 0; b[12] = path; std::memcpy(b + 13, &vel, 2); b[15] = maxDist;
    D2GAME_PACKETS_SendPacket_6FC3C710(pClient, b, sizeof b);
